package com.mindbridge.safety.review;  import com.mindbridge.common.audit.AuditActorType; import com.mindbridge.common.audit.AuditActions; import com.mindbridge.common.audit.AuditCategory; import com.mindbridge.common.audit.AuditService; import com.mindbridge.safety.event.SafetyEventStatus; import com.mindbridge.safety.event.domain.SafetyAction; import com.mindbridge.safety.event.domain.SafetyEvent; import com.mindbridge.safety.event.domain.SafetyEventSource; import com.mindbridge.safety.event.exception.SafetyEventInputException; import com.mindbridge.safety.event.repository.SafetyActionRepository; import com.mindbridge.safety.event.repository.SafetyEventRepository; import com.mindbridge.safety.event.repository.SafetyEventSourceRepository; import com.mindbridge.safety.review.dto.ExpertReviewResponse; import com.mindbridge.safety.review.dto.SafetyEventDetailResponse; import com.mindbridge.safety.review.dto.SafetyEventSummaryResponse; import com.mindbridge.safety.review.dto.SubmitReviewRequest; import org.springframework.data.domain.Page; import org.springframework.data.domain.Pageable; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;  import java.util.List; import java.util.Objects; import java.util.UUID; import java.util.stream.Collectors;  @Service public class ExpertReviewService {      private final SafetyEventRepository safetyEventRepository;     private final SafetyEventSourceRepository safetyEventSourceRepository;     private final SafetyActionRepository safetyActionRepository;     private final ExpertReviewRepository expertReviewRepository;     private final AuditService auditService;      public ExpertReviewService(             SafetyEventRepository safetyEventRepository,             SafetyEventSourceRepository safetyEventSourceRepository,             SafetyActionRepository safetyActionRepository,             ExpertReviewRepository expertReviewRepository,             AuditService auditService) {         this.safetyEventRepository = safetyEventRepository;         this.safetyEventSourceRepository = safetyEventSourceRepository;         this.safetyActionRepository = safetyActionRepository;         this.expertReviewRepository = expertReviewRepository;         this.auditService = auditService;     }      @Transactional(readOnly = true)     public Page<SafetyEventSummaryResponse> listEvents(             SafetyEventStatus status, Short riskLevel, Pageable pageable) {         Page<SafetyEvent> events;         if (status != null && riskLevel != null) {             events = safetyEventRepository.findByStatusAndRiskLevel(status, riskLevel, pageable);         } else if (status != null) {             events = safetyEventRepository.findByStatus(status, pageable);         } else if (riskLevel != null) {             events = safetyEventRepository.findByRiskLevel(riskLevel, pageable);         } else {             events = safetyEventRepository.findAll(pageable);         }         return events.map(this::toSummaryResponse);     }      private SafetyEventSummaryResponse toSummaryResponse(SafetyEvent event) {         long count = expertReviewRepository.countBySafetyEventId(event.getId());         return new SafetyEventSummaryResponse(                 event.getId(), event.getUserId(), event.getRiskLevel(), event.getStatus(),                 event.getSummary(), event.getCreatedAt(), event.getResolvedAt(), (int) count);     }      @Transactional     public SafetyEventDetailResponse getEventDetailAndRecordOpened(UUID eventId) {         SafetyEvent event = safetyEventRepository.findById(eventId)                 .orElseThrow(() -> new SafetyEventInputException("Safety event not found: " + eventId));         List<SafetyEventSource> sources = safetyEventSourceRepository.findBySafetyEventId(eventId);         List<SafetyAction> actions = safetyActionRepository.findBySafetyEventId(eventId);         List<ExpertReview> reviews = expertReviewRepository                 .findBySafetyEventId(eventId, Pageable.unpaged()).getContent();         auditService.record(AuditCategory.SAFETY, AuditActions.EXPERT_REVIEW_OPENED,                 AuditActorType.USER, null, "SafetyEvent", eventId, "eventId=" + eventId);         return toDetailResponse(event, sources, actions, reviews);     }      @Transactional     public ExpertReviewResponse submitReview(UUID eventId, UUID reviewerId, SubmitReviewRequest request) {         Objects.requireNonNull(reviewerId, "reviewerId must not be null");         if (request.decision() == ExpertReviewDecision.DISMISS                 && (request.note() == null || request.note().isBlank())) {             throw new SafetyEventInputException("Note is required when decision is DISMISS");         }         SafetyEvent event = safetyEventRepository.findById(eventId)                 .orElseThrow(() -> new SafetyEventInputException("Safety event not found: " + eventId));         if (event.getStatus() == SafetyEventStatus.RESOLVED                 || event.getStatus() == SafetyEventStatus.DISMISSED) {             throw new SafetyEventInputException("Cannot review an already closed event: " + event.getStatus());         }         if (expertReviewRepository.existsBySafetyEventIdAndReviewerId(eventId, reviewerId)) {             throw new org.springframework.dao.DataIntegrityViolationException(                     "Reviewer " + reviewerId + " has already reviewed event " + eventId);         }         ExpertReview review = ExpertReview.create(UUID.randomUUID(), eventId, reviewerId,                 request.decision(), request.note());         ExpertReview savedReview = expertReviewRepository.save(review);         if (event.getStatus() == SafetyEventStatus.OPEN) {             event.markUnderReview();             safetyEventRepository.save(event);         }         auditService.record(AuditCategory.SAFETY, AuditActions.EXPERT_REVIEW_DECIDED,                 AuditActorType.USER, reviewerId, "SafetyEvent", eventId,                 "eventId=" + eventId + ",decision=" + request.decision());         return toReviewResponse(savedReview);     }      private SafetyEventDetailResponse toDetailResponse(             SafetyEvent event, List<SafetyEventSource> sources,             List<SafetyAction> actions, List<ExpertReview> reviews) {         return new SafetyEventDetailResponse(                 event.getId(), event.getUserId(), event.getRiskLevel(), event.getStatus(),                 event.getSummary(), event.getCreatedAt(), event.getResolvedAt(),                 sources.stream().map(SafetyEventDetailResponse.SourceResponse::new).collect(Collectors.toList()),                 actions.stream().map(SafetyEventDetailResponse.ActionResponse::new).collect(Collectors.toList()),                 reviews.stream().map(this::toReviewResponse).collect(Collectors.toList()));     }      private ExpertReviewResponse toReviewResponse(ExpertReview review) {         return new ExpertReviewResponse(                 review.getId(), review.getSafetyEventId(), review.getReviewerId(),                 "Expert", review.getDecision(), review.getNote(), review.getCreatedAt());     } }